# Look for removed TODO/FIXME/WARNING comments across all patches
gh api repos/manderson240/cohezion/pulls/36/files --paginate | python3 -c "
import json, sys, re
data = json.load(sys.stdin)

for f in data:
    path = f['filename']
    patch = f.get('patch', '')
    if not patch:
        continue

    issues = []
    for line in patch.split('\n'):
        if not line.startswith('-'):
            continue
        # Check for removed comment lines with critical keywords
        if re.search(r'(#|//|<!--|/\*)\s*(TODO|FIXME|NOTE|WARN|WARNING|IMPORTANT|required|do not remove|keep this|dependency|needed for|used by)', line, re.IGNORECASE):
            issues.append(line)

    if issues:
        print(f'=== FILE: {path} ===')
        for issue in issues:
            print(f'  {issue}')
        print()
" 2>/dev/null | head -100

